package com.mohymods.kingdomsmp.economy;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.io.IOException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CommunityContractStoreTest {
 @TempDir Path dir;final UUID p=UUID.randomUUID(),other=UUID.randomUUID();final String project="kingdom_smp:community/grain";
 EconomyStore open()throws IOException{return EconomyStore.open(dir);}
 EconomyStore.PendingItem prepare(EconomyStore s,UUID player,int quantity)throws Exception{return s.prepareCommunityDelivery(UUID.randomUUID(),player,project,1,"minecraft:wheat",quantity,100,1,1000);}
 void commit(EconomyStore s,UUID player,int quantity)throws Exception{var pending=prepare(s,player,quantity);assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));}
 void trials(EconomyStore s)throws Exception{s.changeProfession(UUID.randomUUID(),p,"enroll","","farmer");for(var rank:List.of(ProfessionRank.APPRENTICE,ProfessionRank.JOURNEYMAN))for(int n=1;n<=8;n++){var id=FarmerQuests.id(rank,n);if(FarmerQuests.food(id)){var inputs=new HashMap<String,Integer>();FarmerDeliveries.family(id).forEach(item->inputs.put(item,1));var pending=s.prepareFarmerDelivery(UUID.randomUUID(),p,id,"fixture native food proof",inputs);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));}else if(FarmerQuests.inspection(id))s.approveFarmerInspection(UUID.randomUUID(),other,p,id,"fixture inspected site");else s.completeFarmerQuest(UUID.randomUUID(),p,id,"fixture event proof");}}
 @Test void noGrantBeforeNativeReceiptAndPreReceiptCancel(){var s=assertDoesNotThrow(this::open);assertDoesNotThrow(()->prepare(s,p,64));assertTrue(s.communityProject(project,1).isEmpty());assertTrue(s.mailbox(p).isEmpty());assertFalse(assertDoesNotThrow(()->s.recoverItem(EconomyStore.Receipt.empty())));assertTrue(s.communityProject(project,1).isEmpty());}
 @Test void partialContributionsFundMailAndCompleteSharedGoalPersistently()throws Exception{var s=open();commit(s,p,64);commit(s,other,36);var restored=open();var result=restored.communityProject(project,1).orElseThrow();assertTrue(result.complete());assertEquals(64,result.contributors().get(p).total());assertEquals(36,result.contributors().get(other).total());assertEquals(100,restored.communitySpent(1));assertEquals(64,restored.mailbox(p).getFirst().amount());assertEquals(36,restored.mailbox(other).getFirst().amount());assertThrows(IllegalStateException.class,()->prepare(restored,p,1));}
 @Test void alteredTermsOverfillUnknownItemAndExhaustedPoolNeverPrepare()throws Exception{var s=open();commit(s,p,64);assertThrows(IllegalStateException.class,()->prepare(s,other,37));assertThrows(IllegalStateException.class,()->s.prepareCommunityDelivery(UUID.randomUUID(),p,project,1,"minecraft:wheat",1,200,1,1000));assertThrows(IllegalStateException.class,()->s.prepareCommunityDelivery(UUID.randomUUID(),p,"kingdom_smp:community/bread",1,"minecraft:bread",20,100,3,100));assertThrows(IllegalArgumentException.class,()->s.prepareCommunityDelivery(UUID.randomUUID(),p,"forged",1,"",1,100,1,1000));assertTrue(s.pendingItem().isEmpty());assertEquals(64,s.communitySpent(1));}
 @Test void masterProofRequiresCompletedGoalAndMeaningfulPersonalMasterBandDelivery()throws Exception{var s=open();commit(s,p,64);commit(s,other,26);trials(s);assertEquals(0,s.communityMasterProofs(p));commit(s,p,10);assertEquals(1,open().communityMasterProofs(p));assertEquals(74,s.communityProject(project,1).orElseThrow().contributors().get(p).total());assertEquals(10,s.communityProject(project,1).orElseThrow().contributors().get(p).master());}
 @Test void smallOrPastBandContributionsNeverBecomeRetrospectiveMasterProof()throws Exception{var s=open();commit(s,p,64);commit(s,p,36);trials(s);assertEquals(0,s.communityMasterProofs(p));var pending=s.prepareCommunityDelivery(UUID.randomUUID(),p,project,2,"minecraft:wheat",1,100,1,1000);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));pending=s.prepareCommunityDelivery(UUID.randomUUID(),other,project,2,"minecraft:wheat",64,100,1,1000);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));pending=s.prepareCommunityDelivery(UUID.randomUUID(),other,project,2,"minecraft:wheat",35,100,1,1000);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));assertEquals(0,open().communityMasterProofs(p));}
 @Test void postRenameReceiptRecoveryDoesNotDuplicateProgressOrReward()throws Exception{var s=open();var pending=prepare(s,p,64);var failing=EconomyStore.open(dir,(path,nbt)->{AtomicNbt.write(path,nbt);throw new IOException("after rename");});assertThrows(IOException.class,()->failing.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));var restored=open();assertEquals(64,restored.communityProject(project,1).orElseThrow().delivered());assertEquals(1,restored.mailbox(p).size());assertFalse(restored.recoverItem(new EconomyStore.Receipt(restored.id(),pending.sequence())));}
}
